mapper.select:
/* 관리자 공지 목록 조회 : 비노출 포함, 고정 먼저 */ SELECT N.NTC_MTTR_SN , N.NTC_MTTR_TTL , CASE WHEN N.UPEND_FIX_YN = 'Y' THEN TRUE ELSE FALSE END AS UPEND_FIX_YN , CASE WHEN N.USE_YN = 'Y' THEN TRUE ELSE FALSE END AS USE_YN , N.INQ_CNT , N.NOTI_SNDNG_DT , N.NOTI_TRGT_CNT , N.REG_DT FROM NTC_MTTR N
N.NTC_MTTR_TTL LIKE CONCAT('%', #{keyword}, '%')
ORDER BY N.UPEND_FIX_YN DESC, N.REG_DT DESC, N.NTC_MTTR_SN DESC

mapper.insert:
/* 공지 등록 */
INSERT INTO NTC_MTTR
     ( NTC_MTTR_TTL
     , NTC_MTTR_CN
     , UPEND_FIX_YN
     , USE_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{ntcMttrTtl}
     , #{ntcMttrCn}
     , #{upendFixYn}
     , #{useYn}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 공지 수정 : null 인 값은 그대로 */
UPDATE NTC_MTTR
   SET MDFCN_DT = NOW()
     , MDFR_ID = #{mdfrId}

     , NTC_MTTR_TTL = #{ntcMttrTtl}


     , NTC_MTTR_CN = #{ntcMttrCn}


     , UPEND_FIX_YN = #{upendFixYn}


     , USE_YN = #{useYn}

 WHERE NTC_MTTR_SN = #{ntcMttrSn}

/* 공지 알림 발송 기록 */
UPDATE NTC_MTTR
   SET NOTI_SNDNG_DT = NOW()
     , NOTI_TRGT_CNT = #{notiTrgtCnt}
 WHERE NTC_MTTR_SN = #{ntcMttrSn}
